class HomePage extends StatelessWidget{const HomePage({super.key});@override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:const Text('Sensus Janjang'),backgroundColor:const Color(0xFF14532D),foregroundColor:Colors.white),body:ListView(padding:const EdgeInsets.all(16),children:[const Card(color:Color(0xFFE8F5E9),child:ListTile(title:Text('Iqbal Saimima'),subtitle:Text('Estate KB-1 • Kebun Teluk Kapuas • AFD I'))),Menu(icon:Icons.fact_check,title:'Pemeriksaan',sub:'Mulai sensus baru',tap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const InspectionPage()))),const Menu(icon:Icons.map,title:'Peta',sub:'Lihat track hasil sensus'),const Menu(icon:Icons.storage,title:'Data',sub:'Rekap, upload dan ekspor JSON') ]));}}
class Menu extends StatelessWidget{const Menu({super.key,required this.icon,required this.title,required this.sub,this.tap});final IconData icon;final String title,sub;final VoidCallback? tap;@override Widget build(BuildContext context)=>Card(child:ListTile(onTap:tap,leading:CircleAvatar(backgroundColor:const Color(0xFF166534),foregroundColor:Colors.white,child:Icon(icon)),title:Text(title),subtitle:Text(sub),trailing:const Icon(Icons.chevron_right)));}
